  Ltac shz_adr m ff FA8 SHF k nz off name :=
    let T := fresh "T" in let S := fresh "S" in
    lazymatch type of SHF with rw_cells _ _ _ ?cs =>
      let pre := eval cbv in (firstn k cs) in
      destruct (proj1 (rw_cells_app _ _ _ pre _) SHF) as [_ T];
      cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul length] in T;
      destruct (proj1 (rw_cells_app _ _ _ (repeat (C1 (b8 0)) nz) _) T) as [S _]; clear T;
      assert (name : addressable m (ff + off) (8 * Z.of_nat nz));
      [ split; [lia|]; apply SHAD_of_rw_cells with (n := nz); [lia| clear - FA8; Z.div_mod_to_equations; lia|];
        rewrite <- (sh_shiftr (ff + off)) by lia; rewrite ASHADOW_BASE_val;
        replace (Z.shiftr (ff + off) 3 + 2147450880) with (Z.shiftr ff 3 + 2147450880 + off / 8) by (rewrite !Z.shiftr_div_pow2 by lia; clear - FA8; Z.div_mod_to_equations; lia);
        eapply rw_cells_rebytes; [exact S| cbn; repeat constructor| reflexivity| reflexivity]
      | clear S ]
    end.

  Ltac csz K := cbn [cells_size csize Nat.add Nat.sub Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul length app] in K.
  Ltac csz_goal := cbn [cells_size csize Nat.add Nat.sub Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul length app].
  Ltac join2 H1 H2 name :=
    lazymatch type of H1 with rw_cells _ ?m ?A ?cs1 => lazymatch type of H2 with rw_cells _ _ _ ?cs2 =>
      let cs := eval cbn [app] in (cs1 ++ cs2) in
      assert (name : rw_cells asegs m A cs) by (apply (proj2 (rw_cells_app asegs m A cs1 cs2)); split; [exact H1| eapply rw_at'; [exact H2| csz_goal; clear; lia]])
    end end.

